validateTransportParameters bytes: [UInt8], version: UInt32, expectedSourceConnectionId: [UInt8], expectedOriginalDestinationConnectionId: [UInt8], fromServer: Bool -> Result<PeerTransport, QuicError> {
    [UInt64; ~] => seen!
    false => hasSource!
    false => hasOriginal!
    false => hasVersion!
    UInt64(0) => initialMaxData!
    UInt64(0) => initialMaxStreamDataBidiLocal!
    UInt64(0) => initialMaxStreamDataBidiRemote!
    UInt64(0) => initialMaxStreamsBidi!
    UInt64(65_527) => maxUdpPayloadSize!
    UInt8(3) => ackDelayExponent!
    UInt64(25_000) => maxAckDelay!
    UInt64(0) => maxDatagramFrameSize!
    UIntSize(0) => offset!
    offset! < UIntSize(bytes -> len) -> while {
        decodeTransportParameter(bytes, offset!)? => parameter
        false => duplicate!
        0 => seenIndex!
        seenIndex! < (seen! -> len) -> while {
            seen![seenIndex!] == parameter.id -> if { true => duplicate! }
            seenIndex! + 1 => seenIndex!
        }
        duplicate! -> if { invalidPeerTransport() -> return }
        seen! -> push(parameter.id)

        parameter.id -> when {
            == transport.initialSourceConnectionId() {
                sameBytes(parameter.value, expectedSourceConnectionId) -> unless {
                    invalidPeerTransport() -> return
                }
                true => hasSource!
            }
            == transport.originalDestinationConnectionId() {
                fromServer -> unless { invalidPeerTransport() -> return }
                sameBytes(parameter.value, expectedOriginalDestinationConnectionId) -> unless {
                    invalidPeerTransport() -> return
                }
                true => hasOriginal!
            }
            == transport.versionInformation() {
                decodeVersionInformation(parameter.value)? => information
                information.chosen == version -> unless { invalidPeerTransport() -> return }
                fromServer -> unless {
                    negotiation.validateClient(information) -> when {
                        Ok(valid) {}
                        Err(value) { Result<PeerTransport, QuicError>.Err(protocolFailure(value)) -> return }
                    }
                }
                true => hasVersion!
            }
            == transport.maxUdpPayloadSize() {
                decodeTransportInteger(parameter)? => maximum
                maximum >= 1_200 -> unless { invalidPeerTransport() -> return }
                maximum => maxUdpPayloadSize!
            }
            == transport.initialMaxData() {
                decodeTransportInteger(parameter)? => initialMaxData!
            }
            == transport.initialMaxStreamDataBidiLocal() {
                decodeTransportInteger(parameter)? => initialMaxStreamDataBidiLocal!
            }
            == transport.initialMaxStreamDataBidiRemote() {
                decodeTransportInteger(parameter)? => initialMaxStreamDataBidiRemote!
            }
            == transport.initialMaxStreamsBidi() {
                decodeTransportInteger(parameter)? => initialMaxStreamsBidi!
            }
            == transport.ackDelayExponent() {
                decodeTransportInteger(parameter)? => exponent
                exponent <= 20 -> unless { invalidPeerTransport() -> return }
                UInt8(exponent) => ackDelayExponent!
            }
            == transport.maxAckDelay() {
                decodeTransportInteger(parameter)? => delay
                delay < 16_384 -> unless { invalidPeerTransport() -> return }
                delay * 1_000 => maxAckDelay!
            }
            == transport.activeConnectionIdLimit() {
                decodeTransportInteger(parameter)? => maximum
                maximum >= 2 -> unless { invalidPeerTransport() -> return }
            }
            == transport.maxDatagramFrameSize() {
                decodeTransportInteger(parameter)? => maxDatagramFrameSize!
            }
            else {}
        }
        parameter.nextOffset => offset!
    }
    hasSource! -> unless { invalidPeerTransport() -> return }
    fromServer -> if {
        hasOriginal! -> unless { invalidPeerTransport() -> return }
    }
    version == keys.version2() -> if {
        hasVersion! -> unless { invalidPeerTransport() -> return }
    }
    Result<PeerTransport, QuicError>.Ok(PeerTransport {
        initialMaxData: initialMaxData!
        initialMaxStreamDataBidiLocal: initialMaxStreamDataBidiLocal!
        initialMaxStreamDataBidiRemote: initialMaxStreamDataBidiRemote!
        initialMaxStreamsBidi: initialMaxStreamsBidi!
        maxUdpPayloadSize: maxUdpPayloadSize!
        ackDelayExponent: ackDelayExponent!
        maxAckDelay: maxAckDelay!
        maxDatagramFrameSize: maxDatagramFrameSize!
    })
}

public connectVersion endpoint: move Endpoint, peer: Ipv4Endpoint, version: UInt32 -> Result<Connection, QuicError> uses Network, Random {
    (version == keys.version1() or version == keys.version2()) -> unless {
        Result<Connection, QuicError>.Err(QuicError {
            kind: errors.Kind.InvalidArgument
            code: errors.versionNegotiationError()
        }) -> return
    }
    random8()? => destinationConnectionId
    random8()? => sourceConnectionId
    random32()? => helloRandom
    random32()? => privateKey
    privateKey -> x25519.publicKey => publicKey
    clientTransportParameters(version, sourceConnectionId)? => parameters
    encodeClientHello(helloRandom, publicKey, parameters)? => clientHello
    encodeClientInitial(version, destinationConnectionId, sourceConnectionId, clientHello)? => packet
    sendPacket(endpoint.socket, peer, packet)?
    keys.deriveInitial(version, destinationConnectionId) => initialKeys
    Result<Connection, QuicError>.Ok(Connection {
        socket: endpoint.socket
        identity: endpoint.identity
        peerCertificate: endpoint.peerCertificate
        peer: peer
        localIsServer: false
        version: version
        originalDestinationConnectionId: copy8(destinationConnectionId)
        localConnectionId: sourceConnectionId
        remoteConnectionId: destinationConnectionId
        sendKeys: application.create(initialKeys.clientSecret)
        receiveKeys: application.create(initialKeys.serverSecret)
        nextSendPacketNumber: 0
        nextReceivePacketNumber: 0
        clientPending: true
        clientPrivateKey: privateKey
        clientHello: clientHello
        handshakeReceiveSecret: [0; 32]
        handshakeTranscript: []
        awaitClientFinished: false
        handshakeConfirmed: false
        pendingApplicationPacket: []
        pendingApplicationAck: false
        handshakeDonePending: false
        sentPackets: []
        rtt: recovery.initialRttState()
        congestion: recovery.initialCongestionState(1_200)
        flow: streamState.initialConnectionFlow(1_048_576, 0)
        streamSendMaximum: 0
        streamReceiveMaximum: 262_144
        peerAckDelayExponent: 3
        peerMaxAckDelay: 25_000
        peerMaxDatagramFrameSize: 0
    })
}

public connect endpoint: move Endpoint, peer: Ipv4Endpoint -> Result<Connection, QuicError> uses Network, Random {
    connectVersion(endpoint, peer, keys.version1())
}

public accept endpoint: move Endpoint -> Result<Connection, QuicError> uses Network, Random {
    receivePacket(endpoint.socket)? => received
    acceptClientInitial(received.bytes)? => accepted
    parsePeer(received.sourceAddress, received.sourcePort)? => peer
    decodeClientHello(accepted.clientHello)? => decodedClient
    validateTransportParameters(
        decodedClient.transportParameters,
        accepted.version,
        accepted.clientSourceConnectionId,
        [],
        false)? => peerTransport
    random8()? => serverConnectionId
    random32()? => serverRandom
    random32()? => serverPrivateKey
    serverPrivateKey -> x25519.publicKey => serverPublicKey
    encodeServerHello(serverRandom, serverPublicKey, decodedClient.legacySessionId)? => serverHello
    encodeServerInitial(accepted, serverConnectionId, serverHello)? => initialPacket
    sendPacket(endpoint.socket, peer, initialPacket)?

    x25519.scalarMultiply(serverPrivateKey, decodedClient.keyShare) => sharedSecret
    createServerState(accepted.clientHello)? => handshakeState!
    markServerMessage(handshakeState!, serverHello)?
    serverState.transcriptHash(handshakeState!) => helloTranscriptHash
    tls13.deriveHandshakeFromHash(sharedSecret, helloTranscriptHash) => handshakeSecrets

    serverTransportParameters(
        accepted.version,
        serverConnectionId,
        accepted.originalDestinationConnectionId)? => parameters
    encodeEncryptedExtensions(parameters)? => encryptedExtensions
    markServerMessage(handshakeState!, encryptedExtensions)?
    certificate(endpoint.identity)? => ownCertificate
    encodeCertificateMessage(ownCertificate)? => certificateMessage
    markServerMessage(handshakeState!, certificateMessage)?
    signServerMessage(handshakeState!, endpoint.identity.seed)? => certificateVerify
    serverState.transcriptHash(handshakeState!) => finishedTranscriptHash
    tls13.finishedVerifyDataFromHash(
        handshakeSecrets.serverTrafficSecret,
        finishedTranscriptHash) => serverVerifyData
    encodeFinishedMessage(serverVerifyData)? => serverFinished
    markServerMessage(handshakeState!, serverFinished)?
    serverState.transcriptHash(handshakeState!) => applicationTranscriptHash
    tls13.deriveApplicationFromHash(
        handshakeSecrets.mainSecret,
        applicationTranscriptHash) => applicationSecrets

    [UInt8; ~] => serverFlight!
    serverFlight! -> appendBytes(encryptedExtensions)
    serverFlight! -> appendBytes(certificateMessage)
    serverFlight! -> appendBytes(certificateVerify)
    serverFlight! -> appendBytes(serverFinished)
    encodeHandshakePacket(
        accepted.version,
        accepted.clientSourceConnectionId,
        serverConnectionId,
        serverFlight!,
        handshakeSecrets.serverTrafficSecret)? => handshakePacket
    sendPacket(endpoint.socket, peer, handshakePacket)?
    handshakeState!.transcript.bytes -> copyBytes => handshakeTranscript
    Result<Connection, QuicError>.Ok(Connection {
        socket: endpoint.socket
        identity: endpoint.identity
        peerCertificate: endpoint.peerCertificate
        peer: peer
        localIsServer: true
        version: accepted.version
        originalDestinationConnectionId: copy8(accepted.originalDestinationConnectionId)
        localConnectionId: serverConnectionId
        remoteConnectionId: copy8(accepted.clientSourceConnectionId)
        sendKeys: application.create(applicationSecrets.serverTrafficSecret)
        receiveKeys: application.create(applicationSecrets.clientTrafficSecret)
        nextSendPacketNumber: 0
        nextReceivePacketNumber: 0
        clientPending: false
        clientPrivateKey: [0; 32]
        clientHello: []
        handshakeReceiveSecret: handshakeSecrets.clientTrafficSecret
        handshakeTranscript: handshakeTranscript
        awaitClientFinished: true
        handshakeConfirmed: false
        pendingApplicationPacket: []
        pendingApplicationAck: false
        handshakeDonePending: true
        sentPackets: []
        rtt: recovery.initialRttState()
        congestion: recovery.initialCongestionState(1_200)
        flow: streamState.initialConnectionFlow(1_048_576, peerTransport.initialMaxData)
        streamSendMaximum: peerTransport.initialMaxStreamDataBidiLocal
        streamReceiveMaximum: 262_144
        peerAckDelayExponent: peerTransport.ackDelayExponent
        peerMaxAckDelay: peerTransport.maxAckDelay
        peerMaxDatagramFrameSize: peerTransport.maxDatagramFrameSize
    })
}

copyBytes bytes: [UInt8] -> [UInt8; ~] {
    [UInt8; ~] => copied!
    0 => index!
    index! < (bytes -> len) -> while {
        copied! -> push(bytes[index!])
        index! + 1 => index!
    }
    copied!
}

copyRangeBytes bytes: [UInt8], start: UIntSize -> [UInt8; ~] {
    [UInt8; ~] => copied!
    start => index!
    index! < UIntSize(bytes -> len) -> while {
        copied! -> push(bytes[Int(index!)])
        index! + 1 => index!
    }
    copied!
}

handshakePacket socketValue: socket.UdpSocket -> Result<[UInt8; ~], QuicError> uses Network {
    [UInt8; ~] => selected!
    false => found!
    not found! -> while {
        receivePacket(socketValue)? => received
        packets.longHeaderKind(received.bytes) -> when {
            Ok(kind) {
                kind -> when {
                    == 2 {
                        selected! -> appendBytes(received.bytes)
                        true => found!
                    }
                    == 0 {
                        packets.parseInitialHeader(received.bytes) -> when {
                            Ok(header) {
                                header.packetEnd < UIntSize(received.bytes -> len) -> if {
                                    copyRangeBytes(received.bytes, header.packetEnd) => remaining
                                    packets.longHeaderKind(remaining) -> when {
                                        Ok(remainingKind) {
                                            remainingKind == 2 -> if {
                                                selected! -> appendBytes(remaining)
                                                true => found!
                                            }
                                        }
                                        Err(value) {}
                                    }
                                }
                            }
                            Err(value) { Result<[UInt8; ~], QuicError>.Err(protocolFailure(value)) -> return }
                        }
                    }
                    else {}
                }
            }
            Err(value) { Result<[UInt8; ~], QuicError>.Err(protocolFailure(value)) -> return }
        }
    }
    Result<[UInt8; ~], QuicError>.Ok(selected!)
}

completeClient connection: mut Connection -> Result<Unit, QuicError> uses Network {
    connection.clientPending -> unless { Result<Unit, QuicError>.Ok -> return }
    receivePacket(connection.socket)? => receivedInitial
    openServerInitial(connection, receivedInitial.bytes)? => openedInitial
    copy8(openedInitial.serverSourceConnectionId) => connection.remoteConnectionId
    decodeServerHello(openedInitial.serverHello)? => decodedServer
    (decodedServer.legacySessionId -> len) == 0 -> unless {
        Result<Unit, QuicError>.Err(QuicError {
            kind: errors.Kind.Tls
            code: 47
        }) -> return
    }
    x25519.scalarMultiply(connection.clientPrivateKey, decodedServer.keyShare) => sharedSecret
    createClientState(connection.clientHello)? => handshakeState!
    acceptClientServerMessage(handshakeState!, openedInitial.serverHello)?
    clientState.transcriptHash(handshakeState!) => helloTranscriptHash
    tls13.deriveHandshakeFromHash(sharedSecret, helloTranscriptHash) => handshakeSecrets

    receivePacket(connection.socket)? => receivedHandshake
    openHandshakePacket(
        connection,
        receivedHandshake.bytes,
        handshakeSecrets.serverTrafficSecret)? => openedHandshake
    handshakeMessage(openedHandshake.handshakeBytes, 0)? => encryptedExtensions
    decodeEncryptedExtensionsMessage(encryptedExtensions.bytes)? => decodedExtensions
    validateTransportParameters(
        decodedExtensions.transportParameters,
        connection.version,
        connection.remoteConnectionId,
        connection.originalDestinationConnectionId,
        true)? => peerTransport
    streamState.onMaxData(connection.flow, peerTransport.initialMaxData) => connection.flow
    peerTransport.initialMaxStreamDataBidiRemote => connection.streamSendMaximum
    peerTransport.ackDelayExponent => connection.peerAckDelayExponent
    peerTransport.maxAckDelay => connection.peerMaxAckDelay
    peerTransport.maxDatagramFrameSize => connection.peerMaxDatagramFrameSize
    acceptClientServerMessage(handshakeState!, encryptedExtensions.bytes)?
    handshakeMessage(openedHandshake.handshakeBytes, encryptedExtensions.nextOffset)? => certificateMessage
    acceptClientCertificate(
        handshakeState!,
        certificateMessage.bytes,
        connection.peerCertificate)?
    handshakeMessage(openedHandshake.handshakeBytes, certificateMessage.nextOffset)? => certificateVerify
    acceptClientCertificateVerify(handshakeState!, certificateVerify.bytes)?
    handshakeMessage(openedHandshake.handshakeBytes, certificateVerify.nextOffset)? => serverFinished
    serverFinished.nextOffset == UIntSize(openedHandshake.handshakeBytes -> len) -> unless {
        Result<Unit, QuicError>.Err(QuicError {
            kind: errors.Kind.ProtocolViolation
            code: errors.protocolViolation()
        }) -> return
    }
    clientState.transcriptHash(handshakeState!) => serverFinishedTranscriptHash
    tls13.finishedVerifyDataFromHash(
        handshakeSecrets.serverTrafficSecret,
        serverFinishedTranscriptHash) => expectedServerVerifyData
    acceptClientFinished(
        handshakeState!,
        serverFinished.bytes,
        expectedServerVerifyData)?
    clientState.transcriptHash(handshakeState!) => applicationTranscriptHash
    tls13.deriveApplicationFromHash(
        handshakeSecrets.mainSecret,
        applicationTranscriptHash) => applicationSecrets

    tls13.finishedVerifyDataFromHash(
        handshakeSecrets.clientTrafficSecret,
        applicationTranscriptHash) => clientVerifyData
    encodeFinishedMessage(clientVerifyData)? => clientFinished
    markClientFinished(handshakeState!, clientFinished)?
    encodeHandshakePacket(
        connection.version,
        connection.remoteConnectionId,
        connection.localConnectionId,
        clientFinished,
        handshakeSecrets.clientTrafficSecret)? => clientFinishedPacket
    sendPacket(connection.socket, connection.peer, clientFinishedPacket)?
    application.create(applicationSecrets.clientTrafficSecret) => connection.sendKeys
    application.create(applicationSecrets.serverTrafficSecret) => connection.receiveKeys
    copy32(handshakeSecrets.serverTrafficSecret) => connection.handshakeReceiveSecret
    false => connection.clientPending
    Result<Unit, QuicError>.Ok
}

completeServer connection: mut Connection -> Result<Unit, QuicError> uses Network {
    connection.awaitClientFinished -> unless { Result<Unit, QuicError>.Ok -> return }
    handshakePacket(connection.socket)? => received
    openHandshakePacket(
        connection,
        received,
        connection.handshakeReceiveSecret)? => opened
    opened.nextOffset < UIntSize(received -> len) -> if {
        copyRangeBytes(received, opened.nextOffset) => pending
        connection.pendingApplicationPacket -> appendBytes(pending)
    }
    handshakeMessage(opened.handshakeBytes, 0)? => finished
    finished.nextOffset == UIntSize(opened.handshakeBytes -> len) -> unless {
        Result<Unit, QuicError>.Err(QuicError {
            kind: errors.Kind.ProtocolViolation
            code: errors.protocolViolation()
        }) -> return
    }
    decodeFinishedMessage(finished.bytes)? => actualVerifyData
    sha256.digest(connection.handshakeTranscript) => transcriptHash
    tls13.finishedVerifyDataFromHash(
        connection.handshakeReceiveSecret,
        transcriptHash) => expectedVerifyData
    auth.verifyFinished(expectedVerifyData, actualVerifyData) -> unless {
        Result<Unit, QuicError>.Err(QuicError {
            kind: errors.Kind.Tls
            code: 51
        }) -> return
    }
    false => connection.awaitClientFinished
    true => connection.handshakeConfirmed
    Result<Unit, QuicError>.Ok
}

public openBi connection: mut Connection -> Result<BiStream, QuicError> uses Network {
    connection -> completeClient?
    Result<BiStream, QuicError>.Ok(BiStream {
        id: 0
        sendFlow: streamState.initialSendFlow(connection.streamSendMaximum)
        receiveFlow: streamState.initialReceiveFlow(connection.streamReceiveMaximum)
        finished: false
    })
}

public acceptBi connection: mut Connection -> Result<BiStream, QuicError> uses Network {
    connection -> completeClient?
    connection -> completeServer?
    Result<BiStream, QuicError>.Ok(BiStream {
        id: 0
        sendFlow: streamState.initialSendFlow(connection.streamSendMaximum)
        receiveFlow: streamState.initialReceiveFlow(connection.streamReceiveMaximum)
        finished: false
    })
}

appendPendingControlFrames connection: ref Connection, values: mut [frames.Value; ~] -> Unit {
    connection.pendingApplicationAck -> if {
        values -> push(frames.Value.Ack(frames.Ack {
            largestAcknowledged: connection.nextReceivePacketNumber - 1
            ackDelay: 0
            firstRange: 0
            ranges: []
        }))
    }
    connection.handshakeDonePending -> if {
        values -> push(frames.Value.HandshakeDone)
    }
}

encodeApplicationFrames connection: mut Connection, values: mut [frames.Value; ~] -> Result<[UInt8; ~], QuicError> {
    application.encodeMany(
        connection.version,
        connection.remoteConnectionId,
        connection.nextSendPacketNumber,
        values,
        connection.sendKeys) -> when {
        Ok(packet) {
            false => connection.pendingApplicationAck
            false => connection.handshakeDonePending
            packet -> Result<[UInt8; ~], QuicError>.Ok
        }
        Err(value) { Result<[UInt8; ~], QuicError>.Err(protocolFailure(value)) }
    }
}

encodeStreamPacket connection: mut Connection, channel: ref BiStream, data: move [UInt8; ~], fin: Bool -> Result<[UInt8; ~], QuicError> {
    [frames.Value; ~] => values!
    appendPendingControlFrames(connection, values!)
    values! -> push(frames.Value.Stream(frames.Stream {
        id: channel.id
        offset: channel.sendFlow.sent
        fin: fin
        data: data
    }))
    encodeApplicationFrames(connection, values!)
}

encodeDatagramPacket connection: mut Connection, data: move [UInt8; ~] -> Result<[UInt8; ~], QuicError> {
    [frames.Value; ~] => values!
    appendPendingControlFrames(connection, values!)
    values! -> push(frames.Value.Datagram(frames.Datagram { data: data }))
    encodeApplicationFrames(connection, values!)
}

openPacketMany connection: mut Connection, bytes: [UInt8] -> Result<application.OpenedMany, QuicError> {
    application.openMany(
        connection.version,
        bytes,
        connection.localConnectionId,
        connection.nextReceivePacketNumber,
        connection.receiveKeys) -> when {
        Ok(opened) {
            true => connection.pendingApplicationAck
            opened -> Result<application.OpenedMany, QuicError>.Ok
        }
        Err(value) { Result<application.OpenedMany, QuicError>.Err(protocolFailure(value)) }
    }
}

nowMicros: -> UInt64 uses Clock {
    UInt64(runtime.nowMillis()) * 1_000
}

recordApplicationPacket connection: mut Connection, packetNumber: UInt64, packetSize: UInt64 -> Unit uses Clock {
    connection.sentPackets -> packetRecovery.recordSent(
        packetNumber,
        nowMicros(),
        packetSize,
        true,
        true)
    recovery.onPacketSent(connection.congestion, packetSize, true) => connection.congestion
}

processApplicationAck connection: mut Connection, ack: ref frames.Ack -> Result<Unit, QuicError> uses Clock {
    ack.largestAcknowledged < connection.nextSendPacketNumber -> unless {
        Result<Unit, QuicError>.Err(QuicError {
            kind: errors.Kind.ProtocolViolation
            code: errors.protocolViolation()
        }) -> return
    }
    connection.congestion.bytesInFlight >= connection.congestion.congestionWindow => congestionLimited
    connection.sentPackets -> packetRecovery.processAckScaled(
        ack,
        connection.rtt,
        connection.congestion,
        nowMicros(),
        connection.peerAckDelayExponent,
        connection.peerMaxAckDelay,
        true,
        1_200,
        congestionLimited) -> when {
        Ok(update) {
            update.rtt => connection.rtt
            update.congestion => connection.congestion
            Result<Unit, QuicError>.Ok
        }
        Err(value) { Result<Unit, QuicError>.Err(protocolFailure(value)) }
    }
}

receiveApplicationPacket connection: mut Connection -> Result<[UInt8; ~], QuicError> uses Network {
    (connection.pendingApplicationPacket -> len) > 0 -> if {
        [UInt8; ~] => pending!
        (connection.pendingApplicationPacket -> len) > 0 -> while {
            connection.pendingApplicationPacket -> take(0) => value
            pending! -> push(value)
        }
        Result<[UInt8; ~], QuicError>.Ok(pending!) -> return
    }
    receivePacket(connection.socket)? => received
    Result<[UInt8; ~], QuicError>.Ok(received.bytes)
}

public send connection: mut Connection, channel: mut BiStream, bytes: [UInt8] -> Result<UIntSize, QuicError> uses Network, Clock {
    UInt64(bytes -> len) => length
    streamState.reserveSend(channel.sendFlow, length, false) -> when {
        Ok(next) { next }
        Err(value) { Result<UIntSize, QuicError>.Err(protocolFailure(value)) -> return }
    } => nextStreamFlow
    streamState.reserveConnectionSend(connection.flow, length) -> when {
        Ok(next) { next }
        Err(value) { Result<UIntSize, QuicError>.Err(protocolFailure(value)) -> return }
    } => nextConnectionFlow
    bytes -> copyBytes => data
    encodeStreamPacket(connection, channel, data, false)? => packet
    UInt64(packet -> len) => packetSize
    sendPacket(connection.socket, connection.peer, packet)?
    recordApplicationPacket(connection, connection.nextSendPacketNumber, packetSize)
    nextStreamFlow => channel.sendFlow
    nextConnectionFlow => connection.flow
    connection.nextSendPacketNumber + 1 => connection.nextSendPacketNumber
    Result<UIntSize, QuicError>.Ok(UIntSize(bytes -> len))
}

public finish connection: mut Connection, channel: mut BiStream -> Result<Unit, QuicError> uses Network, Clock {
    streamState.reserveSend(channel.sendFlow, 0, true) -> when {
        Ok(next) { next }
        Err(value) { Result<Unit, QuicError>.Err(protocolFailure(value)) -> return }
    } => nextStreamFlow
    [UInt8; ~] => empty
    encodeStreamPacket(connection, channel, empty, true)? => packet
    UInt64(packet -> len) => packetSize
    sendPacket(connection.socket, connection.peer, packet)?
    recordApplicationPacket(connection, connection.nextSendPacketNumber, packetSize)
    nextStreamFlow => channel.sendFlow
    connection.nextSendPacketNumber + 1 => connection.nextSendPacketNumber
    true => channel.finished
    Result<Unit, QuicError>.Ok
}

unexpectedFrame code: UInt64 -> Result<[UInt8; ~], QuicError> {
    Result<[UInt8; ~], QuicError>.Err(QuicError {
        kind: errors.Kind.ProtocolViolation
        code: code
    })
}

public receive connection: mut Connection, channel: mut BiStream, maxBytes: UIntSize -> Result<[UInt8; ~], QuicError> uses Network, Clock {
    [UInt8; ~] => output!
    false => found!
    not found! -> while {
        receiveApplicationPacket(connection)? => received
        openPacketMany(connection, received)? => opened!
        opened!.packetNumber + 1 => connection.nextReceivePacketNumber
        (opened!.frames -> len) > 0 -> while {
            opened!.frames -> take(0) -> when {
                Stream(value) {
                    UInt64(value.data -> len) => length
                    (value.id == channel.id
                        and value.offset == channel.receiveFlow.highestReceived
                        and (value.data -> len) <= Int(maxBytes)) -> unless {
                        unexpectedFrame(errors.protocolViolation()) -> return
                    }
                    streamState.onReceive(channel.receiveFlow, value.offset, length, value.fin) -> when {
                        Ok(next) { next }
                        Err(error) { Result<[UInt8; ~], QuicError>.Err(protocolFailure(error)) -> return }
                    } => nextReceiveFlow
                    streamState.onConnectionReceive(connection.flow, length) -> when {
                        Ok(next) { next }
                        Err(error) { Result<[UInt8; ~], QuicError>.Err(protocolFailure(error)) -> return }
                    } => nextConnectionFlow
                    nextReceiveFlow => channel.receiveFlow
                    nextConnectionFlow => connection.flow
                    value.fin -> if { true => channel.finished }
                    output! -> appendBytes(value.data)
                    streamState.onConsumed(channel.receiveFlow, length) -> when {
                        Ok(next) { next }
                        Err(error) { Result<[UInt8; ~], QuicError>.Err(protocolFailure(error)) -> return }
                    } => channel.receiveFlow
                    streamState.onConnectionConsumed(connection.flow, length) -> when {
                        Ok(next) { next }
                        Err(error) { Result<[UInt8; ~], QuicError>.Err(protocolFailure(error)) -> return }
                    } => connection.flow
                    true => found!
                }
                Padding(count) {}
                Ping {}
                Ack(ack) { processApplicationAck(connection, ack)? }
                NewConnectionId(value) {}
                RetireConnectionId(sequence) {}
                MaxData(maximum) { streamState.onMaxData(connection.flow, maximum) => connection.flow }
                MaxStreamData(limit) {
                    limit.id == channel.id -> if {
                        streamState.onMaxStreamData(channel.sendFlow, limit.maximum) => channel.sendFlow
                    }
                }
                MaxStreams(limit) {}
                DataBlocked(limit) {}
                StreamDataBlocked(blocked) {}
                StreamsBlocked(blocked) {}
                Crypto(crypto) { unexpectedFrame(6) -> return }
                Datagram(datagram) { unexpectedFrame(48) -> return }
                ConnectionClose(close) {
                    Result<[UInt8; ~], QuicError>.Err(QuicError {
                        kind: errors.Kind.ConnectionClosed
                        code: close.errorCode
                    }) -> return
                }
                HandshakeDone {
                    connection.localIsServer -> if {
                        unexpectedFrame(errors.protocolViolation()) -> return
                    }
                    true => connection.handshakeConfirmed
                }
            }
        }
    }
    Result<[UInt8; ~], QuicError>.Ok(output!)
}

public sendDatagram connection: mut Connection, bytes: [UInt8] -> Result<Unit, QuicError> uses Network, Clock {
    (connection.peerMaxDatagramFrameSize > 0
        and UInt64(bytes -> len) + 1 <= connection.peerMaxDatagramFrameSize) -> unless {
        Result<Unit, QuicError>.Err(QuicError {
            kind: errors.Kind.InvalidArgument
            code: UInt64(bytes -> len)
        }) -> return
    }
    bytes -> copyBytes => data
    encodeDatagramPacket(connection, data)? => packet
    UInt64(packet -> len) => packetSize
    sendPacket(connection.socket, connection.peer, packet)?
    recordApplicationPacket(connection, connection.nextSendPacketNumber, packetSize)
    connection.nextSendPacketNumber + 1 => connection.nextSendPacketNumber
    Result<Unit, QuicError>.Ok
}

public receiveDatagram connection: mut Connection -> Result<[UInt8; ~], QuicError> uses Network, Clock {
    [UInt8; ~] => output!
    false => found!
    not found! -> while {
        receiveApplicationPacket(connection)? => received
        openPacketMany(connection, received)? => opened!
        opened!.packetNumber + 1 => connection.nextReceivePacketNumber
        (opened!.frames -> len) > 0 -> while {
            opened!.frames -> take(0) -> when {
                Datagram(value) {
                    output! -> appendBytes(value.data)
                    true => found!
                }
                Padding(count) {}
                Ping {}
                Ack(ack) { processApplicationAck(connection, ack)? }
                MaxData(maximum) { streamState.onMaxData(connection.flow, maximum) => connection.flow }
                MaxStreamData(limit) {}
                MaxStreams(limit) {}
                DataBlocked(limit) {}
                StreamDataBlocked(blocked) {}
                StreamsBlocked(blocked) {}
                NewConnectionId(value) {}
                RetireConnectionId(sequence) {}
                Crypto(crypto) { unexpectedFrame(6) -> return }
                Stream(streamFrame) { unexpectedFrame(8) -> return }
                ConnectionClose(close) {
                    Result<[UInt8; ~], QuicError>.Err(QuicError {
                        kind: errors.Kind.ConnectionClosed
                        code: close.errorCode
                    }) -> return
                }
                HandshakeDone {
                    connection.localIsServer -> if {
                        unexpectedFrame(errors.protocolViolation()) -> return
                    }
                    true => connection.handshakeConfirmed
                }
            }
        }
    }
    Result<[UInt8; ~], QuicError>.Ok(output!)
}

public close connection: mut Connection, code: UInt32 -> Result<Unit, QuicError> uses Network {
    application.encode(
        connection.version,
        connection.remoteConnectionId,
        connection.nextSendPacketNumber,
        frames.Value.ConnectionClose(frames.ConnectionClose {
            application: true
            errorCode: UInt64(code)
            frameType: 0
            reason: []
        }),
        connection.sendKeys) -> when {
        Ok(packet) {
            sendPacket(connection.socket, connection.peer, packet)?
            connection.nextSendPacketNumber + 1 => connection.nextSendPacketNumber
            Result<Unit, QuicError>.Ok
        }
        Err(value) { Result<Unit, QuicError>.Err(protocolFailure(value)) }
    }
}

namespace sys.quic.application_engine

import sys.quic.error as errors
import sys.quic.frame
import sys.quic.frame_types as frames
import sys.quic.packet
import sys.quic.traffic_keys

public struct KeyState {
    phase: Bool
    secret: [UInt8; 32]
}

public struct Opened {
    packetNumber: UInt64
    keyPhase: Bool
    frame: frames.Value
}

public struct OpenedMany {
    packetNumber: UInt64
    keyPhase: Bool
    frames: [frames.Value; ~]
}

error kind: errors.Kind, code: UInt64 -> errors.Error {
    errors.Error { kind: kind, code: code }
}

sameBool left: Bool, right: Bool -> Bool {
    (left and right) or (not left and not right)
}

copySecret secret: [UInt8; 32] -> [UInt8; 32] {
    [UInt8(0); 32] => copied!
    0 => index!
    index! < 32 -> while {
        secret[index!] => copied![index!]
        index! + 1 => index!
    }
    copied!
}

public create secret: [UInt8; 32] -> KeyState {
    KeyState { phase: false, secret: copySecret(secret) }
}

public update state: mut KeyState -> Unit {
    traffic_keys.nextSecret(state.secret) => state.secret
    not state.phase => state.phase
}

public encode version: UInt32, destinationConnectionId: [UInt8], packetNumber: UInt64, value: move frames.Value, state: ref KeyState -> Result<[UInt8; ~], errors.Error> {
    frame.encode(value)? => plaintext
    traffic_keys.derive(version, state.secret) => keys
    packet.sealOneRtt(
        destinationConnectionId,
        state.phase,
        packetNumber,
        4,
        plaintext,
        keys.key,
        keys.iv,
        keys.headerProtection)
}

public encodeMany version: UInt32, destinationConnectionId: [UInt8], packetNumber: UInt64, values: mut [frames.Value; ~], state: ref KeyState -> Result<[UInt8; ~], errors.Error> {
    frame.encodeAll(values)? => plaintext
    traffic_keys.derive(version, state.secret) => keys
    packet.sealOneRtt(
        destinationConnectionId,
        state.phase,
        packetNumber,
        4,
        plaintext,
        keys.key,
        keys.iv,
        keys.headerProtection)
}

openWithSecret version: UInt32, datagram: [UInt8], destinationConnectionId: [UInt8], expectedPacketNumber: UInt64, expectedPhase: Bool, secret: [UInt8; 32] -> Result<Opened, errors.Error> {
    traffic_keys.derive(version, secret) => keys
    packet.openOneRtt(
        datagram,
        destinationConnectionId,
        expectedPacketNumber,
        keys.key,
        keys.iv,
        keys.headerProtection)? => opened
    sameBool(opened.keyPhase, expectedPhase) -> unless {
        Result<Opened, errors.Error>.Err(error(errors.Kind.ProtocolViolation, UInt64(opened.packetNumber))) -> return
    }
    frame.decode(opened.plaintext, 0)? => decoded
    decoded.nextOffset == UIntSize(opened.plaintext -> len) -> unless {
        Result<Opened, errors.Error>.Err(error(errors.Kind.ProtocolViolation, UInt64(decoded.nextOffset))) -> return
    }
    Result<Opened, errors.Error>.Ok(Opened {
        packetNumber: opened.packetNumber
        keyPhase: opened.keyPhase
        frame: decoded.frame
    })
}

openManyWithSecret version: UInt32, datagram: [UInt8], destinationConnectionId: [UInt8], expectedPacketNumber: UInt64, expectedPhase: Bool, secret: [UInt8; 32] -> Result<OpenedMany, errors.Error> {
    traffic_keys.derive(version, secret) => keys
    packet.openOneRtt(
        datagram,
        destinationConnectionId,
        expectedPacketNumber,
        keys.key,
        keys.iv,
        keys.headerProtection)? => opened
    sameBool(opened.keyPhase, expectedPhase) -> unless {
        Result<OpenedMany, errors.Error>.Err(error(errors.Kind.ProtocolViolation, opened.packetNumber)) -> return
    }
    frame.decodeAll(opened.plaintext)? => decoded
    Result<OpenedMany, errors.Error>.Ok(OpenedMany {
        packetNumber: opened.packetNumber
        keyPhase: opened.keyPhase
        frames: decoded
    })
}

# A peer can initiate a key update without an extra signal. Try the current
# packet-protection keys first, then exactly one RFC 9001 next-secret step.
public open version: UInt32, datagram: [UInt8], destinationConnectionId: [UInt8], expectedPacketNumber: UInt64, state: mut KeyState -> Result<Opened, errors.Error> {
    openWithSecret(
        version,
        datagram,
        destinationConnectionId,
        expectedPacketNumber,
        state.phase,
        state.secret) -> when {
        Ok(opened) { Result<Opened, errors.Error>.Ok(opened) }
        Err(currentError) {
            traffic_keys.nextSecret(state.secret) => nextSecret
            not state.phase => nextPhase
            openWithSecret(
                version,
                datagram,
                destinationConnectionId,
                expectedPacketNumber,
                nextPhase,
                nextSecret) -> when {
                Ok(opened) {
                    nextSecret => state.secret
                    nextPhase => state.phase
                    Result<Opened, errors.Error>.Ok(opened)
                }
                Err(nextError) { Result<Opened, errors.Error>.Err(currentError) }
            }
        }
    }
}

public openMany version: UInt32, datagram: [UInt8], destinationConnectionId: [UInt8], expectedPacketNumber: UInt64, state: mut KeyState -> Result<OpenedMany, errors.Error> {
    openManyWithSecret(
        version,
        datagram,
        destinationConnectionId,
        expectedPacketNumber,
        state.phase,
        state.secret) -> when {
        Ok(opened) { Result<OpenedMany, errors.Error>.Ok(opened) }
        Err(currentError) {
            traffic_keys.nextSecret(state.secret) => nextSecret
            not state.phase => nextPhase
            openManyWithSecret(
                version,
                datagram,
                destinationConnectionId,
                expectedPacketNumber,
                nextPhase,
                nextSecret) -> when {
                Ok(opened) {
                    nextSecret => state.secret
                    nextPhase => state.phase
                    Result<OpenedMany, errors.Error>.Ok(opened)
                }
                Err(nextError) { Result<OpenedMany, errors.Error>.Err(currentError) }
            }
        }
    }
}

namespace sys.quic.connection_state

import sys.quic.error as errors
import sys.quic.frame_types as frames
import sys.quic.stream_state
import sys.quic.stream_types as streams

public struct State {
    localIsServer: Bool
    handshakeConfirmed: Bool
    peerClosed: Bool
    flow: streams.ConnectionFlow
    peerStreamLimits: streams.StreamLimits
}

transportError code: UInt64 -> errors.Error => errors.Error { kind: errors.Kind.Transport, code: code }

public create localIsServer: Bool, receiveMaximum: UInt64, sendMaximum: UInt64, peerBidirectionalStreams: UInt64, peerUnidirectionalStreams: UInt64 -> State => State {
    localIsServer: localIsServer
    handshakeConfirmed: false
    peerClosed: false
    flow: stream_state.initialConnectionFlow(receiveMaximum, sendMaximum)
    peerStreamLimits: stream_state.initialStreamLimits(peerBidirectionalStreams, peerUnidirectionalStreams)
}

public apply state: State, value: move frames.Value -> Result<State, errors.Error> {
    value -> when {
        MaxData(maximum) {
            State {
                localIsServer: state.localIsServer
                handshakeConfirmed: state.handshakeConfirmed
                peerClosed: state.peerClosed
                flow: stream_state.onMaxData(state.flow, maximum)
                peerStreamLimits: state.peerStreamLimits
            } -> Result<State, errors.Error>.Ok
        }
        MaxStreams(limit) {
            State {
                localIsServer: state.localIsServer
                handshakeConfirmed: state.handshakeConfirmed
                peerClosed: state.peerClosed
                flow: state.flow
                peerStreamLimits: stream_state.onMaxStreams(
                    state.peerStreamLimits,
                    limit.bidirectional,
                    limit.maximum)
            } -> Result<State, errors.Error>.Ok
        }
        HandshakeDone {
            state.localIsServer -> if {
                Result<State, errors.Error>.Err(transportError(errors.protocolViolation()))
            } else {
                Result<State, errors.Error>.Ok(State {
                    localIsServer: false
                    handshakeConfirmed: true
                    peerClosed: state.peerClosed
                    flow: state.flow
                    peerStreamLimits: state.peerStreamLimits
                })
            }
        }
        ConnectionClose(close) {
            Result<State, errors.Error>.Ok(State {
                localIsServer: state.localIsServer
                handshakeConfirmed: state.handshakeConfirmed
                peerClosed: true
                flow: state.flow
                peerStreamLimits: state.peerStreamLimits
            })
        }
        Padding(count) { Result<State, errors.Error>.Ok(state) }
        Ping { Result<State, errors.Error>.Ok(state) }
