namespace sys.quic.loss_recovery

import sys.quic.error as errors

public struct RttState {
    initialized: Bool
    latest: UInt64
    minimum: UInt64
    smoothed: UInt64
    variance: UInt64
}

public struct CongestionState {
    congestionWindow: UInt64
    slowStartThreshold: UInt64
    bytesInFlight: UInt64
    recoveryStartTime: UInt64
    inRecovery: Bool
}

public initialRtt: -> UInt64 => 333_000
public timerGranularity: -> UInt64 => 1_000
public packetThreshold: -> UInt64 => 3
maximumDuration: -> UInt64 => 18_446_744_073_709_551_615

maximum left: UInt64, right: UInt64 -> UInt64 {
    left >= right -> if { left } else { right }
}

minimum left: UInt64, right: UInt64 -> UInt64 {
    left <= right -> if { left } else { right }
}

absoluteDifference left: UInt64, right: UInt64 -> UInt64 {
    left >= right -> if { left - right } else { right - left }
}

public initialRttState: -> RttState => RttState {
    initialized: false
    latest: initialRtt()
    minimum: initialRtt()
    smoothed: initialRtt()
    variance: initialRtt() / 2
}

public updateRtt state: RttState, latest: UInt64, ackDelay: UInt64, maxAckDelay: UInt64, applicationData: Bool -> RttState {
    state.initialized -> if {
        minimum(state.minimum, latest) => nextMinimum
        minimum(ackDelay, maxAckDelay) => boundedDelay
        (applicationData and latest >= nextMinimum + boundedDelay) -> if {
            latest - boundedDelay
        } else {
            latest
        } => adjusted
        absoluteDifference(state.smoothed, adjusted) => difference
        RttState {
            initialized: true
            latest: latest
            minimum: nextMinimum
            smoothed: (state.smoothed * 7 + adjusted) / 8
            variance: (state.variance * 3 + difference) / 4
        }
    } else {
        RttState {
            initialized: true
            latest: latest
            minimum: latest
            smoothed: latest
            variance: latest / 2
        }
    }
}

public timeThresholdDelay state: RttState -> UInt64 {
    maximum(state.latest, state.smoothed) => base
    maximum(base + base / 8, timerGranularity())
}

public lostByPacketThreshold largestAcknowledged: UInt64, packetNumber: UInt64 -> Bool {
    largestAcknowledged > packetNumber -> if {
        largestAcknowledged - packetNumber >= packetThreshold()
    } else {
        false
    }
}

public lostByTimeThreshold state: RttState, now: UInt64, sentTime: UInt64 -> Bool {
    now >= sentTime -> if { now - sentTime >= timeThresholdDelay(state) } else { false }
}

public probeTimeout state: RttState, maxAckDelay: UInt64, applicationData: Bool, ptoCount: UInt8 -> Result<UInt64, errors.Error> {
    state.smoothed + maximum(state.variance * 4, timerGranularity()) => timer!
    applicationData -> if { timer! + maxAckDelay => timer! }
    ptoCount - ptoCount => index!
    index! < ptoCount -> while {
        timer! <= maximumDuration() / 2 -> if {
            timer! * 2 => timer!
        } else {
            Result<UInt64, errors.Error>.Err(errors.Error { kind: errors.Kind.InvalidArgument, code: UInt64(ptoCount) }) -> return
        }
        index! + 1 => index!
    }
    Result<UInt64, errors.Error>.Ok(timer!)
}

public initialCongestionWindow maxDatagramSize: UInt64 -> UInt64 {
    minimum(maxDatagramSize * 10, maximum(maxDatagramSize * 2, 14_720))
}

public minimumCongestionWindow maxDatagramSize: UInt64 -> UInt64 => maxDatagramSize * 2

public initialCongestionState maxDatagramSize: UInt64 -> CongestionState => CongestionState {
    congestionWindow: initialCongestionWindow(maxDatagramSize)
    slowStartThreshold: maximumDuration()
    bytesInFlight: 0
    recoveryStartTime: 0
    inRecovery: false
}

public onPacketSent state: CongestionState, sentBytes: UInt64, ackEliciting: Bool -> CongestionState => CongestionState {
    congestionWindow: state.congestionWindow
    slowStartThreshold: state.slowStartThreshold
    bytesInFlight: state.bytesInFlight + (ackEliciting -> if { sentBytes } else { 0 })
    recoveryStartTime: state.recoveryStartTime
    inRecovery: state.inRecovery
}

public onPacketsAcknowledged state: CongestionState, acknowledgedBytes: UInt64, largestAcknowledgedSentTime: UInt64, maxDatagramSize: UInt64, congestionLimited: Bool -> CongestionState {
    minimum(state.bytesInFlight, acknowledgedBytes) => removed
    state.bytesInFlight - removed => nextInFlight
    ((state.inRecovery and largestAcknowledgedSentTime <= state.recoveryStartTime) or not congestionLimited) -> if {
        CongestionState {
            congestionWindow: state.congestionWindow
            slowStartThreshold: state.slowStartThreshold
            bytesInFlight: nextInFlight
            recoveryStartTime: state.recoveryStartTime
            inRecovery: state.inRecovery
        }
    } else {
        state.congestionWindow < state.slowStartThreshold -> if {
            state.congestionWindow + acknowledgedBytes
        } else {
            state.congestionWindow + maxDatagramSize * acknowledgedBytes / state.congestionWindow
        } => nextWindow
        CongestionState {
            congestionWindow: nextWindow
            slowStartThreshold: state.slowStartThreshold
            bytesInFlight: nextInFlight
            recoveryStartTime: state.recoveryStartTime
            inRecovery: state.inRecovery
        }
    }
}

public onPacketsLost state: CongestionState, lostBytes: UInt64, largestLostSentTime: UInt64, now: UInt64, maxDatagramSize: UInt64 -> CongestionState {
    minimum(state.bytesInFlight, lostBytes) => removed
    state.bytesInFlight - removed => nextInFlight
    (state.inRecovery and largestLostSentTime <= state.recoveryStartTime) -> if {
        CongestionState {
            congestionWindow: state.congestionWindow
            slowStartThreshold: state.slowStartThreshold
            bytesInFlight: nextInFlight
            recoveryStartTime: state.recoveryStartTime
            inRecovery: state.inRecovery
        }
    } else {
        maximum(state.congestionWindow / 2, minimumCongestionWindow(maxDatagramSize)) => nextWindow
        CongestionState {
            congestionWindow: nextWindow
            slowStartThreshold: nextWindow
            bytesInFlight: nextInFlight
            recoveryStartTime: now
            inRecovery: true
        }
    }
}

public onPersistentCongestion state: CongestionState, maxDatagramSize: UInt64 -> CongestionState => CongestionState {
    congestionWindow: minimumCongestionWindow(maxDatagramSize)
    slowStartThreshold: state.slowStartThreshold
    bytesInFlight: state.bytesInFlight
    recoveryStartTime: state.recoveryStartTime
    inRecovery: state.inRecovery
}

namespace sys.quic.packet_number

import sys.quic.error as errors

public struct Truncated {
    value: UInt32
    byteCount: UIntSize
}

error code: UInt64 -> errors.Error {
    errors.Error { kind: errors.Kind.Encoding, code: code }
}

window byteCount: UIntSize -> Result<UInt64, errors.Error> {
    byteCount -> when {
        == 1 { Result<UInt64, errors.Error>.Ok(256) }
        == 2 { Result<UInt64, errors.Error>.Ok(65_536) }
        == 3 { Result<UInt64, errors.Error>.Ok(16_777_216) }
        == 4 { Result<UInt64, errors.Error>.Ok(4_294_967_296) }
        else { Result<UInt64, errors.Error>.Err(error(UInt64(byteCount))) }
    }
}

public selectLength packetNumber: UInt64, hasAcknowledged: Bool, largestAcknowledged: UInt64 -> UIntSize {
    hasAcknowledged -> unless { 4 -> return }
    packetNumber >= largestAcknowledged -> unless { 4 -> return }
    packetNumber - largestAcknowledged => distance
    distance -> when {
        < 128 { 1 }
        < 32_768 { 2 }
        < 8_388_608 { 3 }
        else { 4 }
    }
}

public truncate packetNumber: UInt64, byteCount: UIntSize -> Result<Truncated, errors.Error> {
    packetNumber >= 4_611_686_018_427_387_904 -> if {
        Result<Truncated, errors.Error>.Err(error(packetNumber)) -> return
    }
    window(byteCount)? => packetWindow
    Result<Truncated, errors.Error>.Ok(Truncated {
        value: UInt32(packetNumber % packetWindow)
        byteCount: byteCount
    })
}

# `expectedPacketNumber` is one greater than the largest authenticated packet
# number in this packet-number space, matching RFC 9000 Appendix A.3.
public restore expectedPacketNumber: UInt64, truncatedPacketNumber: UInt32, byteCount: UIntSize -> Result<UInt64, errors.Error> {
    expectedPacketNumber > 4_611_686_018_427_387_904 -> if {
        Result<UInt64, errors.Error>.Err(error(expectedPacketNumber)) -> return
    }
    window(byteCount)? => packetWindow
    packetWindow / 2 => halfWindow
    expectedPacketNumber / packetWindow * packetWindow + UInt64(truncatedPacketNumber) => candidate
    (candidate + halfWindow <= expectedPacketNumber
        and candidate < 4_611_686_018_427_387_904 - packetWindow) -> if {
        Result<UInt64, errors.Error>.Ok(candidate + packetWindow) -> return
    }
    (candidate > expectedPacketNumber + halfWindow and candidate >= packetWindow) -> if {
        Result<UInt64, errors.Error>.Ok(candidate - packetWindow) -> return
    }
    candidate < 4_611_686_018_427_387_904 -> if {
        Result<UInt64, errors.Error>.Ok(candidate)
    } else {
        Result<UInt64, errors.Error>.Err(error(candidate))
    }
}

namespace sys.quic.packet_recovery

import sys.quic.error as errors
import sys.quic.frame
import sys.quic.frame_types as frames
import sys.quic.loss_recovery as recovery

public struct SentPacket {
    number: UInt64
    sentTime: UInt64
    size: UInt64
    ackEliciting: Bool
    inFlight: Bool
}

public struct Update {
    rtt: recovery.RttState
    congestion: recovery.CongestionState
    acknowledgedBytes: UInt64
    lostBytes: UInt64
    acknowledgedPackets: UInt64
    lostPackets: UInt64
}

public recordSent packets: mut [SentPacket; ~], number: UInt64, sentTime: UInt64, size: UInt64, ackEliciting: Bool, inFlight: Bool -> Unit {
    packets -> push(SentPacket {
        number: number
        sentTime: sentTime
        size: size
        ackEliciting: ackEliciting
        inFlight: inFlight
    })
}

scaleAckDelay value: UInt64, exponent: UInt8 -> Result<UInt64, errors.Error> {
    value => scaled!
    UInt8(0) => shift!
    shift! < exponent -> while {
        scaled! <= 9_223_372_036_854_775_807 -> unless {
            Result<UInt64, errors.Error>.Err(errors.Error {
                kind: errors.Kind.ProtocolViolation
                code: value
            }) -> return
        }
        scaled! * 2 => scaled!
        shift! + 1 => shift!
    }
    Result<UInt64, errors.Error>.Ok(scaled!)
}

public processAckScaled packets: mut [SentPacket; ~], ack: ref frames.Ack, rtt: recovery.RttState, congestion: recovery.CongestionState, now: UInt64, ackDelayExponent: UInt8, maxAckDelay: UInt64, applicationData: Bool, maxDatagramSize: UInt64, congestionLimited: Bool -> Result<Update, errors.Error> {
    scaleAckDelay(ack.ackDelay, ackDelayExponent)? => ackDelay
    now - now => acknowledgedBytes!
    now - now => lostBytes!
    now - now => acknowledgedPackets!
    now - now => lostPackets!
    now - now => largestAcknowledgedSentTime!
    now - now => largestLostSentTime!
    now - now => latestRtt!
    false => hasAcknowledgedSentTime!
    false => hasLostSentTime!
    false => hasRttSample!
    packets -> len => remaining!
    remaining! > 0 -> while {
        packets -> take(0) => packet
        frame.acknowledges(ack, packet.number)? => acknowledged
        acknowledged -> if {
            acknowledgedPackets! + 1 => acknowledgedPackets!
            packet.inFlight -> if { acknowledgedBytes! + packet.size => acknowledgedBytes! }
            (not hasAcknowledgedSentTime! or packet.sentTime > largestAcknowledgedSentTime!) -> if {
                packet.sentTime => largestAcknowledgedSentTime!
                true => hasAcknowledgedSentTime!
            }
            (packet.number == ack.largestAcknowledged and packet.ackEliciting and now >= packet.sentTime) -> if {
                now - packet.sentTime => latestRtt!
                true => hasRttSample!
            }
        } else {
            (recovery.lostByPacketThreshold(ack.largestAcknowledged, packet.number)
                or recovery.lostByTimeThreshold(rtt, now, packet.sentTime)) -> if {
                lostPackets! + 1 => lostPackets!
                packet.inFlight -> if { lostBytes! + packet.size => lostBytes! }
                (not hasLostSentTime! or packet.sentTime > largestLostSentTime!) -> if {
                    packet.sentTime => largestLostSentTime!
                    true => hasLostSentTime!
                }
            } else {
                packets -> push(packet)
            }
        }
        remaining! - 1 => remaining!
    }

    hasRttSample! -> if {
        recovery.updateRtt(rtt, latestRtt!, ackDelay, maxAckDelay, applicationData)
    } else {
        rtt
    } => nextRtt
    hasAcknowledgedSentTime! -> if {
        recovery.onPacketsAcknowledged(
            congestion,
            acknowledgedBytes!,
            largestAcknowledgedSentTime!,
            maxDatagramSize,
            congestionLimited)
    } else {
        congestion
    } => acknowledgedCongestion
    hasLostSentTime! -> if {
        recovery.onPacketsLost(
            acknowledgedCongestion,
            lostBytes!,
            largestLostSentTime!,
            now,
            maxDatagramSize)
    } else {
        acknowledgedCongestion
    } => nextCongestion
    Update {
        rtt: nextRtt
        congestion: nextCongestion
        acknowledgedBytes: acknowledgedBytes!
        lostBytes: lostBytes!
        acknowledgedPackets: acknowledgedPackets!
        lostPackets: lostPackets!
    } -> Result<Update, errors.Error>.Ok
}

public processAck packets: mut [SentPacket; ~], ack: ref frames.Ack, rtt: recovery.RttState, congestion: recovery.CongestionState, now: UInt64, maxAckDelay: UInt64, applicationData: Bool, maxDatagramSize: UInt64, congestionLimited: Bool -> Result<Update, errors.Error> {
    packets -> processAckScaled(
        ack,
        rtt,
        congestion,
        now,
        0,
        maxAckDelay,
        applicationData,
        maxDatagramSize,
        congestionLimited)
}

