    phase -> when {
        SendCertificateVerify { true }
        SendServerHello { false }
        SendEncryptedExtensions { false }
        SendCertificate { false }
        SendServerFinished { false }
        AwaitClientFinished { false }
        Connected { false }
        Failed { false }
    }
}

public signServerCertificateVerify state: mut State, seed: [UInt8] -> Result<[UInt8; ~], errors.Error> {
    state.phase -> isSendCertificateVerify -> unless {
        phases.Phase.Failed => state.phase
        Result<[UInt8; ~], errors.Error>.Err(error(10)) -> return
