        }
        Err(signError) {
            phases.Phase.Failed => state.phase
            Result<[UInt8; ~], errors.Error>.Err(signError)
        }
    }
}

public acceptClientFinished state: mut State, message: [UInt8], expectedVerifyData: [UInt8; 32] -> Result<Unit, errors.Error> {
    state.phase -> isAwaitClientFinished -> unless {
        phases.Phase.Failed => state.phase
        Result<Unit, errors.Error>.Err(error(10)) -> return
